insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1239, 'Merge Piles', 'n piles of stones stand in a row; pile i has a_i stones. In one move you merge two neighbouring piles into one pile, and the move costs the total number of stones in the new pile. You keep merging until only one pile is left. What is the smallest possible total cost?', 'The first line contains n (1 ≤ n ≤ 400). The second line contains n integers (1 ≤ a_i ≤ 10^6).', 'Print the minimum total cost.', 'In the first example merge 1 and 2 (cost 3), then 3 and 3 (cost 6), then 6 and 4 (cost 10): 19 in total.', '[{"input":"4\n1 2 3 4\n","output":"19"},{"input":"3\n5 5 5\n","output":"25"},{"input":"1\n7\n","output":"0"}]'::jsonb, array['dp']::text[], 2400, 2000, 'public') on conflict (id) do nothing;
